{"file_path":"./src/lcs.js","content":"/**
 * Compute the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines (exact string comparison). When two
 * subsequences are equally long, ties are broken by preferring matches that
 * come earliest, walking both documents from the start and advancing the
 * side with the longer remaining subsequence, preferring to advance the
 * base when they tie.
 *
 * Returns a list of changes, each `{ baseStart, baseEnd, sideStart, sideEnd }`,
 * describing a run of base lines (possibly empty) replaced by a run of side
 * lines (possibly empty), ordered by position in the base.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        const skipBase = dp[i + 1][j]
        const skipSide = dp[i][j + 1]
        dp[i][j] = skipBase >= skipSide ? skipBase : skipSide
      }
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let prevI = 0
  let prevJ = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      if (prevI < i || prevJ < j) {
        changes.push({ baseStart: prevI, baseEnd: i, sideStart: prevJ, sideEnd: j })
      }
      i++
      j++
      prevI = i
      prevJ = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, sideStart: prevJ, sideEnd: m })
  }
  return changes
}
"}

